#!/usr/bin/env node
/* eslint-disable */
// Generated by @@generator@@. Runs in CI and in the release gate.
//
// Checks that the GitHub Actions workflows keep secrets away from the app's dependencies and out
// of command lines and logs:
//
//   node .github/mobile-cicd/check-workflow-secrets.mjs [workflow.yml ...]   (default: .github/workflows/*.yml)
//
// Rules:
//   job-env        No secret in a workflow- or job-level env: a secret goes to the one step that needs it.
//   inline-secret  No ${{ secrets.X }} inside run: (it would be pasted into the script) or with:,
//                  and no toJSON(secrets).
//   after-deps     A store secret (App Store Connect, iOS signing, Android upload key, Play key) is
//                  never given to a step that runs dependency code, or comes after one, in its job:
//                  install scripts, Expo plugins, CocoaPods, Gradle and Xcode build scripts could
//                  read it, and anything they leave running could read later steps too.
//   password-arg   A *PASSWORD* variable is never expanded on a command line (other processes can read
//                  arguments). Pass it through the environment (keytool -storepass:env NAME).
//   xtrace         No `set -x` / `bash -x` in a step that has a secret: it prints every command.
//   cache          A job that runs dependency code doesn't save the gem cache (bundler-cache), and a job
//                  with store secrets doesn't restore caches dependency code can write.
//   unpinned       A job with store secrets pins every action to a full commit SHA.
//
// Exit codes: 0 no findings, 1 findings, 2 a file could not be read.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const STORE_SECRETS = [
  'APP_STORE_CONNECT_API_KEY_ID',
  'APP_STORE_CONNECT_ISSUER_ID',
  'APP_STORE_CONNECT_API_KEY',
  'IOS_DISTRIBUTION_CERTIFICATE',
  'IOS_DISTRIBUTION_CERTIFICATE_PASSWORD',
  'IOS_PROVISIONING_PROFILE',
  'ANDROID_KEYSTORE',
  'ANDROID_KEYSTORE_PASSWORD',
  'ANDROID_KEY_ALIAS',
  'ANDROID_KEY_PASSWORD',
  'GOOGLE_PLAY_SERVICE_ACCOUNT_JSON',
];

// ------------------------------------------------------------------ a small YAML reader
// Enough YAML for GitHub workflows: block mappings and sequences, block scalars (| and >),
// quoted and plain scalars, comments, flat flow sequences ([a, 'b']). Other flow collections
// ({a: b}, nested [[...]]) are kept as plain strings.
// Every node is { kind: 'map' | 'seq' | 'str', value, line }.

function stripComment(text) {
  let quote = null;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quote) {
      if (c === quote) quote = null;
    } else if (c === '"' || c === "'") {
      if (i === 0 || /\s/.test(text[i - 1])) quote = c;
    } else if (c === '#' && (i === 0 || /\s/.test(text[i - 1]))) {
      return text.slice(0, i).trimEnd();
    }
  }
  return text.trimEnd();
}

function scalar(raw) {
  const t = raw.trim();
  if (t.startsWith("'") && t.endsWith("'") && t.length >= 2) return t.slice(1, -1).replace(/''/g, "'");
  if (t.startsWith('"') && t.endsWith('"') && t.length >= 2) {
    return t.slice(1, -1).replace(/\\(["\\nt])/g, (_, c) => ({ n: '\n', t: '\t' })[c] ?? c);
  }
  return t;
}

// [a, 'b, c'] -> ['a', 'b, c'], or null when it is not a flat flow sequence.
function flowSequence(v) {
  if (!v.startsWith('[') || !v.endsWith(']')) return null;
  const items = [];
  let quote = null;
  let current = '';
  for (const c of v.slice(1, -1)) {
    if (quote) {
      if (c === quote) quote = null;
      current += c;
    } else if (c === '"' || c === "'") {
      quote = c;
      current += c;
    } else if (c === '[' || c === ']' || c === '{' || c === '}') {
      return null;
    } else if (c === ',') {
      items.push(current);
      current = '';
    } else {
      current += c;
    }
  }
  if (quote) return null;
  if (current.trim() !== '' || items.length) items.push(current);
  return items.map(scalar);
}

export function parseYaml(text) {
  const lines = text.split('\n').map((raw, i) => ({ raw, no: i + 1, indent: raw.match(/^ */)[0].length }));
  let pos = 0;
  const isBlank = (l) => /^\s*(#.*)?$/.test(l.raw);
  const skip = () => {
    while (pos < lines.length && isBlank(lines[pos])) pos++;
  };

  function blockScalar(header, parentIndent, line) {
    const folded = header.startsWith('>');
    const body = [];
    let indent = null;
    while (pos < lines.length) {
      const l = lines[pos];
      if (l.raw.trim() === '') {
        body.push('');
        pos++;
        continue;
      }
      if (l.indent <= parentIndent) break;
      if (indent === null) indent = l.indent;
      body.push(l.raw.slice(Math.min(indent, l.indent)));
      pos++;
    }
    while (body.length && body[body.length - 1] === '') body.pop();
    return { kind: 'str', value: body.join(folded ? ' ' : '\n'), line };
  }

  function value(rest, indent, line) {
    const v = stripComment(rest);
    if (/^[|>][-+0-9]*$/.test(v)) return blockScalar(v, indent, line);
    const flow = flowSequence(v);
    if (flow) return { kind: 'seq', value: flow.map((item) => ({ kind: 'str', value: item, line })), line };
    if (v !== '') return { kind: 'str', value: scalar(v), line };
    skip();
    if (pos >= lines.length) return { kind: 'str', value: '', line };
    const next = lines[pos];
    if (next.indent > indent || (next.indent === indent && /^\s*- |^\s*-$/.test(next.raw))) return node(next.indent);
    return { kind: 'str', value: '', line };
  }

  function mapEntry(map, text, indent, line) {
    const m = text.match(/^((?:"[^"]*"|'[^']*'|[^:#])+?):(?:\s+(.*)|$)/);
    if (!m) throw new Error(`line ${line}: cannot read "${text.trim()}"`);
    map.value[scalar(m[1])] = value(m[2] ?? '', indent, line);
  }

  function node(indent) {
    skip();
    const first = lines[pos];
    if (/^\s*-( |$)/.test(first.raw)) {
      const seq = { kind: 'seq', value: [], line: first.no };
      while (pos < lines.length) {
        skip();
        const l = lines[pos];
        if (!l || l.indent !== indent || !/^\s*-( |$)/.test(l.raw)) break;
        pos++;
        const after = l.raw.slice(indent + 1);
        const content = after.replace(/^ +/, '');
        const itemIndent = indent + 1 + (after.length - content.length);
        if (content === '' || content.startsWith('#')) {
          seq.value.push(value('', indent, l.no));
        } else if (/^((?:"[^"]*"|'[^']*'|[^:#'"])+?):(\s|$)/.test(content)) {
          const map = { kind: 'map', value: {}, line: l.no };
          mapEntry(map, content, itemIndent, l.no);
          readMap(map, itemIndent);
          seq.value.push(map);
        } else {
          seq.value.push(value(content, indent, l.no));
        }
      }
      return seq;
    }
    const map = { kind: 'map', value: {}, line: first.no };
    readMap(map, indent);
    return map;
  }

  function readMap(map, indent) {
    while (pos < lines.length) {
      skip();
      const l = lines[pos];
      if (!l || l.indent !== indent || /^\s*-( |$)/.test(l.raw)) break;
      pos++;
      mapEntry(map, l.raw.slice(indent), indent, l.no);
    }
  }

  skip();
  if (pos >= lines.length) return { kind: 'map', value: {}, line: 1 };
  const root = node(lines[pos].indent);
  skip();
  if (pos < lines.length) throw new Error(`line ${lines[pos].no}: unexpected indentation`);
  return root;
}

// ------------------------------------------------------------------ the rules

// secrets.NAME or secrets['NAME'], inside ${{ }} expressions only.
const EXPRESSION = /\$\{\{([\s\S]*?)\}\}/g;
const SECRET_REF = /\bsecrets\s*(?:\.\s*([A-Za-z_][A-Za-z0-9_]*)|\[\s*['"]([A-Za-z_][A-Za-z0-9_]*)['"]\s*\])/g;
const secretNames = (text) =>
  [...String(text).matchAll(EXPRESSION)].flatMap((e) => [...e[1].matchAll(SECRET_REF)].map((m) => m[1] ?? m[2]));
const allSecrets = (text) => [...String(text).matchAll(EXPRESSION)].some((e) => /toJSON\s*\(\s*secrets\s*\)/i.test(e[1]));
const str = (n) => (n && n.kind === 'str' ? n.value : '');
const entries = (n) => (n && n.kind === 'map' ? Object.entries(n.value) : []);

// A step that runs code from the app's dependencies, or sets up the toolchain to.
const DEPENDENCY_ACTIONS = /^(actions\/setup-node|pnpm\/action-setup|oven-sh\/setup-bun)@/;
const DEPENDENCY_COMMANDS =
  /(^|[\s;&|(`])(npm|npx|pnpm|pnpx|yarn|corepack|bun|bunx|\.\/gradlew|gradlew|gradle|xcodebuild|pod|expo)(\s|$)|fastlane\s+ios\s+build\b/m;

function runsDependencyCode(step) {
  return DEPENDENCY_ACTIONS.test(str(step.value.uses)) || DEPENDENCY_COMMANDS.test(str(step.value.run));
}

// Lines of a run: script that expand a *PASSWORD* variable as a command argument. Allowed:
// [[ ]] tests, assignments, and echo / printf into a pipe (shell builtins, no process arguments).
function passwordArguments(script) {
  const found = [];
  script.split('\n').forEach((line, i) => {
    const names = [...line.matchAll(/\$\{?([A-Za-z_][A-Za-z0-9_]*PASSWORD[A-Za-z0-9_]*)/g)].map((m) => m[1]);
    if (!names.length) return;
    const t = line.trim();
    const allowed =
      /^(if\s+|elif\s+|!\s*)?\[\[.*\]\]/.test(t) ||
      /^(export\s+|local\s+|readonly\s+)?[A-Za-z_][A-Za-z0-9_]*=/.test(t) ||
      /^(echo|printf)\b[^|]*\|/.test(t);
    if (!allowed) found.push({ offset: i, names });
  });
  return found;
}

export function checkWorkflow(text, file = 'workflow.yml') {
  const findings = [];
  const add = (line, rule, message) => findings.push({ file, line, rule, message });
  const doc = parseYaml(text);
  const pinnedSha = /^[^@]+@[0-9a-f]{40}$/;

  for (const [name, n] of entries(doc.value?.env)) {
    for (const s of secretNames(str(n))) add(n.line, 'job-env', `workflow env ${name} holds secret ${s}: give it to the step that needs it`);
  }

  for (const [jobId, job] of entries(doc.value?.jobs)) {
    for (const [name, n] of entries(job.value.env)) {
      for (const s of secretNames(str(n))) add(n.line, 'job-env', `job ${jobId}: env ${name} holds secret ${s}: give it only to the step that needs it`);
    }
    const steps = job.value.steps?.kind === 'seq' ? job.value.steps.value.filter((s) => s.kind === 'map') : [];
    let firstDependencyStep = null;
    let lastStoreSecretStep = -1;
    const caches = []; // { index, step, bundler }

    steps.forEach((step, index) => {
      const label = `job ${jobId}, step "${str(step.value.name) || str(step.value.uses) || index + 1}"`;
      const run = step.value.run;
      const uses = str(step.value.uses);
      if (firstDependencyStep === null && runsDependencyCode(step)) firstDependencyStep = index;

      if (run) {
        if (allSecrets(str(run))) add(run.line, 'inline-secret', `${label}: toJSON(secrets) exposes every secret`);
        for (const s of secretNames(str(run))) {
          add(run.line, 'inline-secret', `${label}: \${{ secrets.${s} }} is pasted into the script; pass it through the step's env and use "$${s}"`);
        }
        for (const p of passwordArguments(str(run))) {
          add(run.line + (run.value.includes('\n') ? 1 + p.offset : 0), 'password-arg',
            `${label}: ${p.names.join(', ')} is expanded on a command line; pass it through the environment (e.g. keytool -storepass:env NAME)`);
        }
      }
      for (const [name, n] of entries(step.value.with)) {
        if (allSecrets(str(n))) add(n.line, 'inline-secret', `${label}: with.${name} gets toJSON(secrets)`);
        for (const s of secretNames(str(n))) add(n.line, 'inline-secret', `${label}: with.${name} gets secret ${s}; actions in release jobs take secrets through env only`);
      }

      const stepSecrets = entries(step.value.env).flatMap(([, n]) => secretNames(str(n)).map((s) => ({ s, line: n.line })));
      const storeSecrets = stepSecrets.filter(({ s }) => STORE_SECRETS.includes(s));
      if (storeSecrets.length) lastStoreSecretStep = index;
      if (storeSecrets.length && firstDependencyStep !== null) {
        const where = firstDependencyStep === index ? 'this step runs dependency code' : `step ${firstDependencyStep + 1} of this job already ran dependency code`;
        for (const { s, line } of storeSecrets) {
          add(line, 'after-deps', `${label}: store secret ${s}, but ${where}. Use it in a job of its own, or before the first dependency step`);
        }
      }
      if (stepSecrets.length && run && /(^|\n)\s*set\s+-[a-wyz]*x|\bbash\s+-[a-wyz]*x/.test(str(run))) {
        add(run.line, 'xtrace', `${label}: set -x prints commands with secret values`);
      }
      if (/^actions\/cache(\/restore)?@/.test(uses) || (DEPENDENCY_ACTIONS.test(uses) && str(step.value.with?.value?.cache))) {
        caches.push({ index, step, bundler: false });
      }
      if (/^ruby\/setup-ruby@/.test(uses) && str(step.value.with?.value?.['bundler-cache']) === 'true') {
        caches.push({ index, step, bundler: true });
      }
    });

    for (const { index, step, bundler } of caches) {
      // The gem cache is saved when the job ends, after any dependency code in it has run.
      if (bundler && firstDependencyStep !== null) {
        add(step.line, 'cache', `job ${jobId}: bundler-cache in a job that runs dependency code; that code could plant gems that the jobs with store secrets then load`);
      }
      // Caches that dependency code writes (npm, Gradle, ...) must not be restored before a store secret is used.
      if (!bundler && index < lastStoreSecretStep) {
        add(step.line, 'cache', `job ${jobId}: restores a cache that dependency code can write, before a step with store secrets`);
      }
    }
    if (lastStoreSecretStep >= 0) {
      for (const step of steps) {
        const uses = str(step.value.uses);
        if (uses && !uses.startsWith('./') && !uses.startsWith('docker://') && !pinnedSha.test(uses)) {
          add(step.value.uses.line, 'unpinned', `job ${jobId}: ${uses} is not pinned to a commit SHA, in a job with store secrets`);
        }
      }
    }
  }
  return findings;
}

function main() {
  let files = process.argv.slice(2);
  if (files.includes('-h') || files.includes('--help')) {
    console.log(fs.readFileSync(fileURLToPath(import.meta.url), 'utf8').split('\n').slice(3, 24).join('\n'));
    return;
  }
  if (!files.length) {
    const dir = '.github/workflows';
    files = fs.existsSync(dir) ? fs.readdirSync(dir).filter((f) => /\.ya?ml$/.test(f)).map((f) => path.join(dir, f)) : [];
  }
  let findings = [];
  for (const f of files) {
    try {
      findings = findings.concat(checkWorkflow(fs.readFileSync(f, 'utf8'), f));
    } catch (e) {
      console.error(`${f}: ${e.message}`);
      process.exit(2);
    }
  }
  for (const x of findings) console.log(`${x.file}:${x.line}  [${x.rule}]  ${x.message}`);
  if (findings.length) {
    console.log(`\n${findings.length} problem(s). Rules: node .github/mobile-cicd/check-workflow-secrets.mjs --help`);
    process.exit(1);
  }
  console.log(`Secrets OK in ${files.length} workflow file(s).`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) main();
